bool ParkingHouse::removeCar(const std::string& regNumber) {
    for (auto it = cars.begin(); it != cars.end(); ++it) {
        if (it->regNumber == regNumber) {
            cars.erase(it);
            return true;
        }
    }
    return false;
}
